test_snippets.java:
public static void check(Solution solution) {
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"abcabc","bcabc","cabc","abcd"}), new int[]{'abca', '', '', 'd'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"aaa","aab","aba","abb"}), new int[]{'aaa', 'aab', 'ba', 'bb'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"abc","bcd","abcd"}), new int[]{'', '', 'abcd'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"abcd","bcde","cdef","defg"}), new int[]{'a', 'bcde', 'cdef', 'g'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"hello","world","hel","wor","ld"}), new int[]{'ll', 'rl', '', '', ''});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"unique","strings","array","test"}), new int[]{'q', 'g', 'a', 'es'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"cab","ad","bad","c"}), new int[]{'ab', '', 'ba', ''});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"aaaa","aaab","aabb","abbb"}), new int[]{'aaaa', 'aaab', 'aabb', 'bbb'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"xyz","zyx","yzx"}), new int[]{'xy', 'yx', 'zx'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"abcde","bcdef","cdefg","defgh"}), new int[]{'a', 'bcdef', 'cdefg', 'h'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"a","b","c","d"}), new int[]{'a', 'b', 'c', 'd'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"hello","world","python","programming"}), new int[]{'e', 'd', 't', 'a'});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"same","same","same","same"}), new int[]{'', '', '', ''});
    assert Arrays.equals(solution.shortestSubstrings(new int[]{"banana","bandana","band"}), new int[]{'nan', 'da', ''});
